/**
 * 苏住房后端本地联调脚本
 *
 * 用途：一键完成「启动后端 → 登录取 token → 调用防汛业务接口」的联调闭环。
 *
 * 前置：已构建的 jar（D:\repository\苏住房后端 各模块 target 下）
 *
 * 用法：
 *   node artifacts/backend-integration.mjs login          # 仅登录拿 token
 *   node artifacts/backend-integration.mjs patrol         # 登录并调巡检接口
 */
import crypto from 'node:crypto'

// ---- 联调环境常量（来自各服务 bootstrap.yml + common-utils/AESUtil.java）----
const FRAMEWORK_BASE = 'http://127.0.0.1:9211' // common-framework-server
const PROPERTY_BASE = 'http://127.0.0.1:9604' // zhi2-property-server
// 多租户项目标识头，缺失会被 TraceWebMvcFilter 拦截（MissingRequestHeaderException）
const PROJECT_ID = '1'

// 登录密码 AES 规则：AES/CBC/PKCS5Padding，KEY/IV 见 common-utils AESUtil
const AES_KEY = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal', 'utf8')
const AES_IV = Buffer.from('A-16-Byte-String', 'utf8')

function encryptPassword(plain) {
  const cipher = crypto.createCipheriv('aes-256-cbc', AES_KEY, AES_IV)
  return Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]).toString('base64')
}

async function post(url, body, headers = {}) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': PROJECT_ID, ...headers },
    body: JSON.stringify(body),
  })
  return { status: res.status, json: await res.json() }
}

async function get(url, headers = {}) {
  const res = await fetch(url, { headers: { 'zhi-project-id': PROJECT_ID, ...headers } })
  return { status: res.status, json: await res.json() }
}

export async function login(username, password) {
  const { status, json } = await post(`${FRAMEWORK_BASE}/v2.0/security/auth/login`, {
    username,
    password: encryptPassword(password),
  })
  if (json?.code !== 200) throw new Error(`登录失败 HTTP ${status}: ${json?.msg}`)
  return json.data.accessToken
}

async function main() {
  const cmd = process.argv[2] ?? 'login'
  const username = process.env.INTEGRATION_USER ?? 'zsbase'
  const password = process.env.INTEGRATION_PASSWORD
  if (!password) throw new Error('请设置环境变量 INTEGRATION_PASSWORD')

  const token = await login(username, password)
  console.log(`✅ 登录成功 user=${username} accessToken=${token.slice(0, 32)}...`)

  if (cmd === 'patrol') {
    const auth = { Authorization: token }
    const item = await get(`${PROPERTY_BASE}/v2.0/property/patrol/item/page?pageNum=1&pageSize=5`, auth)
    console.log('巡检项:', JSON.stringify(item.json))
    const me = await get(`${FRAMEWORK_BASE}/v2.0/system/user/getByUserName/${username}`, auth)
    console.log('当前用户:', JSON.stringify(me.json.data?.sysUser?.userName ?? me.json.code))
  }
}

if (import.meta.url === `file://${process.argv[1].replace(/\\/g, '/')}`) {
  main().catch(e => {
    console.error('❌', e.message)
    process.exit(1)
  })
}

